        #                 "network_fee": 0.0,
        #                 "coinbase_networks": [
        #                     {
        #                         "display_name": "Ethereum",
        #                         "resource_name": "networks/ethereum-mainnet"
        #                     }
        #                 ],
        #                 "network_currency": "AAVE",
        #                 "min_confirmations": 0,
        #                 "currency_long": "Aave",
